function keypadKnightStrings(n: number): number {
  const next = [[4, 6], [6, 8], [7, 9], [4, 8], [0, 3, 9], [], [0, 1, 7], [2, 6], [1, 3], [2, 4]];
  const count = (d: number, left: number): number => {
    if (left === 0) return 1;
    let total = 0;
    for (const e of next[d]) total = (total + count(e, left - 1)) % 1000000007;
    return total;
  };
  let total = 0;
  for (let d = 0; d < 10; d++) total = (total + count(d, n - 1)) % 1000000007;
  return total;
}

