function keypadKnightStrings(n: number): number {
  if (n === 1) return 10;
  const MOD = 1000000007;
  // a: ends on a corner, b: on 2 or 8, c: on 4 or 6, d: on 0. 5 is a dead end after one digit.
  let a = 4, b = 2, c = 2, d = 1;
  for (let step = 1; step < n; step++) {
    const na = (2 * b + 2 * c) % MOD; // 2 and 8 reach two corners each; so do 4 and 6
    const nb = a;                     // each corner reaches one of 2, 8
    const nc = (a + 2 * d) % MOD;     // each corner reaches one of 4, 6; 0 reaches both
    const nd = c;                     // 4 and 6 each reach 0
    a = na; b = nb; c = nc; d = nd;
  }
  return (a + b + c + d) % MOD;
}

